{
  "skill": "iam",
  "framework": "CIS AWS Foundations v1.5.0 + AWS Security Best Practices",
  "description": "Comprehensive Identity and Access Management (IAM) security checks",
  "items": [
    {
      "id": "IAM-001",
      "cis_id": "1.5",
      "title": "Root account must have MFA enabled",
      "severity": "Critical",
      "description": "MFA on root account prevents unauthorized access even if root credentials are compromised. Root has no limits on actions.",
      "evidence_files": [
        "users.json",
        "account-summary.json"
      ],
      "check_keywords": [
        "root",
        "mfa_active",
        "MFA",
        "multi-factor"
      ],
      "remediation": "Enable MFA on root account via AWS Console \u2192 Account Settings \u2192 Multi-factor Authentication",
      "pci_dss": [
        {
          "control": "8.4.1",
          "reason": "This control requires MFA for all non-console administrative access into the Cardholder Data Environment (CDE). The root user is the highest privileged account, and enabling MFA is a direct implementation of this requirement to protect it."
        },
        {
          "control": "7.2.1",
          "reason": "This control demands access to be based on job classification and function, following the principle of least privilege. Securing the root account with MFA ensures that only the true owner can perform the unrestricted actions associated with this unique, highly-privileged role."
        }
      ]
    },
    {
      "id": "IAM-002",
      "cis_id": "1.2",
      "title": "IAM users should have MFA enabled (especially privileged users)",
      "severity": "Critical",
      "description": "MFA provides additional layer of security. Critical for users with administrative or console access permissions.",
      "evidence_files": [
        "users.json"
      ],
      "check_keywords": [
        "mfa_active",
        "console access",
        "admin",
        "AdministratorAccess"
      ],
      "remediation": "Enable MFA for each IAM user with console access. Enforce via policies if needed.",
      "pci_dss": [
        {
          "control": "8.4.2",
          "reason": "This control requires MFA for all access into the CDE. Enforcing MFA for all IAM users, especially those with access to the CDE, directly meets this requirement."
        },
        {
          "control": "8.5.1",
          "reason": "This control specifies that MFA must use at least two different factor types and that success of all is required for access. Enabling MFA for IAM users is the first step in implementing a compliant MFA system."
        }
      ]
    },
    {
      "id": "IAM-003",
      "cis_id": "1.3",
      "title": "Remove unused IAM credentials (>90 days inactive)",
      "severity": "High",
      "description": "Inactive credentials increase attack surface. Remove or rotate credentials that haven't been used in 90+ days.",
      "evidence_files": [
        "users.json"
      ],
      "check_keywords": [
        "inactive",
        "90 days",
        "last_used",
        "never used"
      ],
      "remediation": "Remove inactive access keys. For users still needed, force rotation via rotation policy.",
      "pci_dss": [
        {
          "control": "8.2.6",
          "reason": "This control requires that inactive user accounts are removed or disabled within 90 days. This IAM check directly enforces this rule for credentials, reducing the risk of dormant accounts being compromised."
        }
      ]
    },
    {
      "id": "IAM-004",
      "cis_id": "1.11",
      "title": "Access keys should be rotated every 90 days",
      "severity": "Critical",
      "description": "Regular rotation reduces impact of compromised credentials. AWS recommends 90-day rotation.",
      "evidence_files": [
        "users.json"
      ],
      "check_keywords": [
        "access_key",
        "create_date",
        "90 days",
        "rotation",
        "age"
      ],
      "remediation": "Implement automated key rotation. Create new key \u2192 Update applications \u2192 Delete old key after verification.",
      "pci_dss": [
        {
          "control": "8.3.9",
          "reason": "This control requires changing passwords/passphrases at least every 90 days for single-factor authentication. While access keys are not passwords, they are authentication factors, and rotating them every 90 days applies the same security principle to programmatic access."
        }
      ]
    },
    {
      "id": "IAM-005",
      "cis_id": "1.12",
      "title": "IAM password policy minimum length should be 14+ characters",
      "severity": "High",
      "description": "Longer passwords reduce brute-force attack risk. 14+ chars recommended.",
      "evidence_files": [
        "password-policy.json"
      ],
      "check_keywords": [
        "MinimumPasswordLength",
        "password",
        "length"
      ],
      "remediation": "Set: aws iam update-account-password-policy --minimum-password-length 14",
      "pci_dss": [
        {
          "control": "8.3.6",
          "reason": "This control requires passwords/passphrases to have a minimum length of 12 characters. Enforcing a length of 14+ characters exceeds this minimum requirement, strengthening security against brute-force attacks."
        }
      ]
    },
    {
      "id": "IAM-006",
      "cis_id": "1.13",
      "title": "IAM password policy should prevent password reuse",
      "severity": "Medium",
      "description": "Prevents users from reusing old passwords. Should remember at least 24 previous passwords.",
      "evidence_files": [
        "password-policy.json"
      ],
      "check_keywords": [
        "PasswordReusePrevention",
        "reuse",
        "previous"
      ],
      "remediation": "Set: aws iam update-account-password-policy --password-reuse-prevention 24",
      "pci_dss": [
        {
          "control": "8.3.7",
          "reason": "This control mandates that new passwords/passphrases cannot be the same as the four previously used ones. Configuring a reuse prevention of 24 significantly exceeds this requirement, enhancing password history protection."
        }
      ]
    },
    {
      "id": "IAM-007",
      "cis_id": "1.16",
      "title": "Inline policies must not be used. Use managed policies instead",
      "severity": "Medium",
      "description": "Managed policies provide version control, reusability, and easier delegation. Inline policies are deprecated.",
      "evidence_files": [
        "users.json",
        "roles.json",
        "groups.json"
      ],
      "check_keywords": [
        "inline",
        "inline policy",
        "AssumeExecutionRolePermissions"
      ],
      "remediation": "Migrate inline policies to managed policies using CloudFormation or AWS CLI.",
      "pci_dss": [
        {
          "control": "7.2.2",
          "reason": "This control requires assigning access based on job classification and least privilege. Managed policies facilitate this by creating reusable sets of permissions for specific job functions, making access control more standardized, auditable, and less prone to error than managing numerous inline policies."
        }
      ]
    },
    {
      "id": "IAM-008",
      "cis_id": "1.20",
      "title": "No policy should have full administrative permissions (*:*)",
      "severity": "Critical",
      "description": "Policies granting all actions on all resources violate principle of least privilege.",
      "evidence_files": [
        "policies.json",
        "users.json",
        "roles.json",
        "groups.json"
      ],
      "check_keywords": [
        "*:*",
        "Action.*:*",
        "Resource.*:*",
        "AdministratorAccess"
      ],
      "remediation": "Review policies. Replace broad permissions with specific actions and resources.",
      "pci_dss": [
        {
          "control": "7.2.1",
          "reason": "This is a direct implementation of the principle of 'least privileges required to perform a job function.' A policy with '*:*' grants maximum privilege, which is the opposite of the least privilege principle mandated by this control."
        },
        {
          "control": "7.3.3",
          "reason": "This control requires access control systems to be set to 'deny all' by default. Granting '*:*' permissions effectively sets the default to 'allow all', directly contravening this foundational security principle."
        }
      ]
    },
    {
      "id": "IAM-009",
      "cis_id": "1.6",
      "title": "Root account should not have active access keys",
      "severity": "Critical",
      "description": "Root account with access keys provides programmatic access with unlimited permissions. Highest risk.",
      "evidence_files": [
        "users.json",
        "account-summary.json"
      ],
      "check_keywords": [
        "root",
        "access_key",
        "active keys",
        "access_key_1_active"
      ],
      "remediation": "Delete root access keys: aws iam delete-access-key --access-key-id KEY_ID (requires root login)",
      "pci_dss": [
        {
          "control": "2.2.2",
          "reason": "This control requires managing vendor default accounts, including changing passwords or disabling them if not used. The root account is the ultimate 'default' account, and disabling its programmatic access keys is a critical hardening step."
        },
        {
          "control": "7.2.1",
          "reason": "The root account should not be used for daily operational tasks. Prohibiting access keys for the root account enforces the principle of least privilege by forcing the use of IAM roles and users with specific, limited permissions for programmatic access."
        }
      ]
    },
    {
